import {REVIEWER_FIELDS,RATING_CRITERIA,TESTIMONIAL_SLOTS,TESTIMONIAL_FIELDS,reviewerBinding,reviewerReadiness,calculateRating,exportReviewer} from './review-reviewer-domain.mjs?v=2';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountReviewer({root,controller,materials}){
  let message='',failed=false,errors={};
  const valueAt=path=>path.split('.').reduce((value,key)=>value?.[key],controller.current().state);
  const token=path=>'reviewer-'+path.replaceAll('.','-');
  function field(path,label,{area=false,placeholder=''}={}){const value=valueAt(path),error=errors[path];return `<label for="${token(path)}">${esc(label)}${area?`<textarea id="${token(path)}" data-reviewer-field="${path}" rows="3" placeholder="${esc(placeholder)}" ${error?'aria-invalid="true"':''}>${esc(value)}</textarea>`:`<input id="${token(path)}" data-reviewer-field="${path}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${path.endsWith('.score')?'inputmode="decimal"':''} ${error?'aria-invalid="true"':''}>`}${error?`<span class="review-field-error">${esc(error)}</span>`:''}</label>`}
  const check=(path,label)=>`<label class="review-analysis-check"><input type="checkbox" data-reviewer-field="${path}" ${valueAt(path)?'checked':''}>${esc(label)}</label>`;
  function refresh(){
    const item=controller.current(),state=item.state,readiness=reviewerReadiness(state,materials.current().draft),rating=readiness.rating;
    root.querySelector('[data-reviewer-status]').textContent=message||(JSON.stringify(state)!==item.saved?'Alterações ainda não salvas.':item.savedAt?'Rascunho recuperado deste navegador.':'Preencha o relato real; você pode salvar e completar depois.');
    root.querySelector('[data-reviewer-status]').classList.toggle('review-error',failed);
    root.querySelector('[data-reviewer-quality]').textContent=readiness.label;
    root.querySelector('[data-reviewer-gaps]').innerHTML=readiness.gaps.length?readiness.gaps.map(gap=>`<li>${esc(gap)}</li>`).join(''):'<li>Nenhuma pendência estrutural. Confira os relatos antes de concluir.</li>';
    root.querySelector('[data-reviewer-rating]').textContent=!state.rating.include?'Sem nota na saída da página.':rating.invalid.length?'Corrija as notas inválidas.':rating.value===null?'Nenhum critério avaliado.':`${rating.value.toFixed(1)} / 10 · ${rating.included.length} de 4 critérios${rating.partial?' · avaliação parcial':''}.`;
    root.querySelector('[data-reviewer-excluded]').textContent=state.rating.include?`Fora do cálculo: ${rating.excluded.join(', ')||'nenhum'}.`:'';
    root.querySelector('[data-rating-fields]').hidden=!state.rating.include;
    root.querySelector('[data-testimonial-fields]').hidden=!state.includeTestimonials;
    root.querySelector('[data-reviewer-binding]').hidden=state.binding===reviewerBinding(materials.current().draft);
    for(const node of root.querySelectorAll('input[type="checkbox"][data-reviewer-field]'))node.checked=Boolean(valueAt(node.dataset.reviewerField));
    const reviewed=root.querySelector('[data-reviewer-reviewed]');reviewed.checked=state.reviewed&&readiness.ready;
  }
  function render(){
    const item=controller.current(),current=materials.current();
    root.innerHTML=`<p>Use a experiência da pessoa que realmente utilizou o produto. Registre apenas dados e identificações autorizados para a review.</p><p>Estrutura do modelo: contexto e motivação pessoal → descoberta → dúvidas reais → decisão → rotina → resultados e limites. Nas observações, registre o que motivou a busca e o contexto familiar, se houver. Só mencione acompanhamento médico ou prescrição quando isso fizer parte do relato real.</p>
      <label for="reviewer-review">Review selecionada<select id="reviewer-review" data-reviewer-review>${materials.list().map(row=>`<option value="${esc(row.draft.id)}" ${row.draft.id===current.draft.id?'selected':''}>${esc(row.draft.product||'Nova review (salve no passo 1)')} · ${esc(row.draft.market||'mercado a definir')} · ${esc(row.draft.id.slice(0,8))}</option>`).join('')}</select></label>
      <p data-reviewer-status role="status" aria-live="polite" class="review-analysis-status"></p>${item.error?`<p class="review-error" role="alert">Não foi possível ler o registro: ${esc(item.error)}. O conteúdo anterior será preservado.</p>`:''}
      <div class="review-analysis-warning" data-reviewer-binding hidden><p>O produto ou mercado mudou. Confira se os relatos correspondem à oferta atual.</p><button type="button" class="btn hub-standard-action" data-reviewer-action="binding">Confirmo que os relatos correspondem ao produto atual</button></div>
      <section><h4>1. Reviewer e experiência real</h4><div class="review-form-grid">${REVIEWER_FIELDS.slice(0,6).map(([key,label])=>field('reviewer.'+key,label)).join('')}</div><details open><summary>Relato: descoberta, decisão, rotina e resultado</summary>${REVIEWER_FIELDS.slice(6).map(([key,label])=>field('reviewer.'+key,label,{area:true,placeholder:key==='skepticism'?'Resposta necessária para concluir: se não houve desconfiança, escreva “não houve”. Não crie uma objeção.':key==='negatives'?'Descreva os pontos reais; se não houve, informe explicitamente.':''})).join('')}</details>${check('reviewer.realUseConfirmed','Confirmo que este relato é de uma pessoa que realmente usou o produto.')}${check('reviewer.publishConsent','Confirmo autorização para usar a identificação pública e o relato informados.')}</section>
      <section><h4>2. Nota editorial</h4>${check('rating.include','Incluir uma nota editorial nesta review')}<p>Método inicial: média simples dos critérios avaliados, pesos iguais, escala de 0 a 10. Critérios em branco ficam fora do cálculo. Você pode optar por não usar nota.</p><strong class="review-rating-value" data-reviewer-rating></strong><p data-reviewer-excluded></p><div data-rating-fields>${RATING_CRITERIA.map(([key,label])=>`<div class="review-rating-criterion"><h4>${esc(label)}</h4>${field('rating.'+key+'.score','Nota de 0 a 10 (deixe em branco se não avaliado)',{placeholder:'Ex.: 8,5'})}${field('rating.'+key+'.reason','Motivo da avaliação',{area:true})}</div>`).join('')}${check('rating.confirmed','Valido este método e a nota calculada, considerando os critérios não avaliados.')}<p>A nota representa avaliação editorial da experiência; não comprova eficácia científica.</p></div></section>
      <section><h4>3. Depoimentos do modelo</h4>${check('includeTestimonials','Preparar os dois depoimentos previstos no modelo')}<p>O reviewer e os dois depoimentos são fontes distintas. Sem relatos reais disponíveis, mantenha as pendências ou desative a seção.</p><div data-testimonial-fields>${TESTIMONIAL_SLOTS.map(([slot,label])=>`<details class="review-analysis-block"><summary>${esc(label)}</summary><div class="review-testimonial-body">${TESTIMONIAL_FIELDS.map(([key,title])=>field('testimonials.'+slot+'.'+key,title,{area:key==='quote'})).join('')}${check('testimonials.'+slot+'.realConfirmed','Confirmo que este depoimento é real e corresponde à origem informada.')}${check('testimonials.'+slot+'.publishConsent','Confirmo autorização para usar o relato, a identificação e a imagem informados.')}</div></details>`).join('')}</div></section>
      <section><h4>4. Conferência e saída</h4><p class="review-analysis-warning" data-reviewer-quality></p><details><summary>Ver pendências deste passo</summary><ul data-reviewer-gaps></ul></details><label class="review-analysis-check"><input type="checkbox" data-reviewer-reviewed>Revisei o relato, a nota e os depoimentos para a próxima etapa.</label><div class="review-actions"><button type="button" class="btn primary hub-standard-action" data-reviewer-action="save" ${item.error||!current.revision?'disabled':''}>Salvar reviewer</button><button type="button" class="btn hub-standard-action" data-reviewer-action="md">Baixar reviewer .md</button><button type="button" class="btn hub-standard-action" data-reviewer-action="json">Baixar reviewer .json</button></div><p>Salvar guarda um rascunho neste navegador, sem publicar. Baixe uma cópia externa. Alterações retiram a marca de revisão; histórico anterior é preservado.</p></section>`;
    refresh();
  }
  function update(event){const path=event.target.dataset.reviewerField;if(!path)return;controller.update(path,event.target.type==='checkbox'?event.target.checked:event.target.value);message='';failed=false;if(errors[path]){delete errors[path];event.target.removeAttribute('aria-invalid')}refresh()}
  root.addEventListener('input',event=>{if(event.target.type!=='checkbox')update(event)});
  root.addEventListener('change',event=>{
    try{if(event.target.matches('[data-reviewer-review]')){materials.select(event.target.value);errors={};message='';failed=false;render()}
    else if(event.target.matches('[data-reviewer-reviewed]')){controller.setReviewed(event.target.checked);message='';failed=false;refresh()}
    else if(event.target.type==='checkbox')update(event)}catch(error){message=error.message;failed=true;refresh()}
  });
  root.addEventListener('click',async event=>{
    const button=event.target.closest('[data-reviewer-action]'),action=button?.dataset.reviewerAction;if(!action)return;
    try{failed=false;
      if(action==='binding'){controller.confirmBinding();message='Correspondência confirmada. Reconfirme uso real, autorizações dos relatos e nota para a oferta atual.';refresh()}
      if(action==='save'){button.disabled=true;const id=materials.current().draft.id;try{if(navigator.locks?.request)await navigator.locks.request('hub-review-reviewer-'+id,()=>controller.save(id));else controller.save(id);errors={};message='Reviewer salvo neste navegador; revisões anteriores preservadas.';render()}finally{button.disabled=false}}
      if(action==='md'||action==='json'){const state=controller.current().state,draft=materials.current().draft,readiness=reviewerReadiness(state,draft),payload=action==='json'?JSON.stringify({...state,reviewed:state.reviewed&&readiness.ready,summary:{product:draft.product,rating:state.rating.include?calculateRating(state):null,readiness:readiness.label}},null,2):exportReviewer(state,draft),url=URL.createObjectURL(new Blob([payload],{type:action==='json'?'application/json;charset=utf-8':'text/markdown;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`review-${draft.id.slice(0,8)}-reviewer.${action}`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message='Reviewer exportado com as edições atuais.';refresh()}
    }catch(error){errors=error.fields||{};message=`Não foi possível concluir: ${error.message} As edições continuam nesta tela.`;failed=true;render();root.querySelector('[aria-invalid="true"]')?.focus()}
  });
  render();
}
